mapper.select:
select #{level} as level, concat(runtime_base.runtime_side, '|', runtime_base.match_key) as item_key, max(runtime_base.note_no) as note_no, null as pdf_title, null as pdf_detail, null as pdf_locator, null as excel_title, null as excel_detail, null as excel_locator, true as runtime_recognized, 'RUNTIME_ONLY' as runtime_status, cast(count(*) as signed) as runtime_match_count, runtime_base.runtime_side as runtime_side, max(concat(coalesce(runtime_base.table_title, '未命名表'), ' / runtime ', runtime_base.level)) as runtime_title, max(concat( '行：', coalesce(nullif(runtime_base.row_label, ''), nullif(runtime_base.row_key, ''), nullif(runtime_base.row_path, ''), '未识别行名'), '；列：', coalesce(nullif(runtime_base.column_label, ''), nullif(runtime_base.column_key, ''), nullif(runtime_base.column_path, ''), '未识别列名'), '；值：', coalesce(nullif(runtime_base.value_text, ''), nullif(runtime_base.value_signature, ''), '空') )) as runtime_detail, max(coalesce(nullif(runtime_base.cell_coordinate, ''), nullif(runtime_base.source_locator, ''), nullif(runtime_base.locator_method, ''))) as runtime_locator, max(coalesce(nullif(runtime_base.value_text, ''), nullif(runtime_base.value_signature, ''))) as runtime_value_text, max(runtime_base.confidence_level) as runtime_confidence_level, max(runtime_base.source_artifact) as runtime_source_artifact, max(runtime_base.locator_method) as runtime_locator_method, max(md5(concat( 'runtimeOnly|', cast(#{runId} as char), '|', #{noteNo}, '|', #{level}, '|', runtime_base.runtime_side, '|', runtime_base.match_key ))) as decision_key, 'runtimeOnly' as view_mode, max(d.decision) as decision, max(d.comment) as decision_comment, max(d.alias_text) as alias_text, max(d.merge_target_key) as merge_target_key, max(d.reviewer) as reviewer, max(d.reviewed_at) as reviewed_at, max(d.updated_at) as decision_updated_at from ( select runtime_side, note_no, level, as match_key, table_title, table_profile_id, row_label, row_key, row_path, column_label, column_key, column_path, value_text, normalized_value, value_signature, cell_coordinate, source_locator, locator_method, confidence_level, source_artifact from runtime_structure_item where project_id = #{projectId} and run_id = #{runId} and note_no = #{noteNo} and level = #{level}
and ( table_title like concat('%', #{keyword}, '%') or table_profile_id like concat('%', #{keyword}, '%') or row_key like concat('%', #{keyword}, '%') or row_label like concat('%', #{keyword}, '%') or row_path like concat('%', #{keyword}, '%') or column_key like concat('%', #{keyword}, '%') or column_label like concat('%', #{keyword}, '%') or column_path like concat('%', #{keyword}, '%') or value_text like concat('%', #{keyword}, '%') or normalized_value like concat('%', #{keyword}, '%') or value_signature like concat('%', #{keyword}, '%') or cell_coordinate like concat('%', #{keyword}, '%') or source_locator like concat('%', #{keyword}, '%') or locator_method like concat('%', #{keyword}, '%')
or like concat('%', #{normalizedKeyword}, '%')
)
) runtime_base left join ( select distinct s.side, as match_key from s where s.project_id = #{projectId} and s.note_no = #{noteNo} ) source_keys on source_keys.side = runtime_base.runtime_side and source_keys.match_key = runtime_base.match_key left join structure_gt_decision d on d.project_id = #{projectId} and d.decision_key = md5(concat( 'runtimeOnly|', cast(#{runId} as char), '|', #{noteNo}, '|', #{level}, '|', runtime_base.runtime_side, '|', runtime_base.match_key )) where source_keys.match_key is null group by runtime_base.runtime_side, runtime_base.match_key order by runtime_base.runtime_side, runtime_base.match_key
